class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def build(pairs, rates):
            adj = {}
            nodes = set()
            for (a, b), r in zip(pairs, rates):
                nodes.add(a)
                nodes.add(b)
                adj.setdefault(a, []).append((b, r))
                adj.setdefault(b, []).append((a, 1.0 / r))
            return adj, nodes

        def relax(adj, nodes, src):
            # max multiplier from src to every node
            best = {x: 0.0 for x in nodes}
            best[src] = 1.0
            changed = True
            it = 0
            while changed and it <= len(nodes) + 5:
                changed = False
                it += 1
                for u in list(best.keys()):
                    if best[u] <= 0:
                        continue
                    for v, r in adj.get(u, []):
                        val = best[u] * r
                        if val > best[v] + 1e-12:
                            best[v] = val
                            changed = True
            return best

        adj1, nodes1 = build(pairs1, rates1)
        adj2, nodes2 = build(pairs2, rates2)

        allnodes = nodes1 | nodes2 | {initialCurrency}

        # Day 1: from initial
        if initialCurrency in nodes1:
            best1 = relax(adj1, nodes1, initialCurrency)
        else:
            best1 = {initialCurrency: 1.0}

        # Day 2: for each currency c, max multiplier from c to initial
        if initialCurrency in nodes2:
            ans = 0.0
            for c in allnodes:
                if best1.get(c, 0.0) <= 0:
                    continue
                if c == initialCurrency:
                    m2 = 1.0
                    # could still convert around on day 2 and return; relax from initial
                    r2 = relax(adj2, nodes2, initialCurrency)
                    m2 = max(m2, r2.get(initialCurrency, 0.0))
                elif c in nodes2:
                    r2 = relax(adj2, nodes2, c)
                    m2 = r2.get(initialCurrency, 0.0)
                else:
                    m2 = 0.0
                if m2 <= 0:
                    continue
                ans = max(ans, best1[c] * m2)
            if ans == 0.0:
                ans = max(best1.values())
            return float(ans)
        else:
            ans = max(best1.values())
            return float(ans)
