                        best[v] = best[u] * w
                        changed = True
                if not changed:
                    break
            return best

        e1 = build(pairs1, rates1)
        e2 = build(pairs2, rates2)
        nodes = set([initialCurrency])
        for a, b in pairs1:
            nodes.add(a); nodes.add(b)
        for a, b in pairs2:
            nodes.add(a); nodes.add(b)
        nodes = list(nodes)

        # Day 1: max amount of each currency from 1.0 initial
        d1 = best_from(initialCurrency, e1, nodes)

        # Day 2: max rate from each currency c to initialCurrency
        # Compute by reverse: for each c, best_from(c) on e2 and take value at initial
