NAMES = ["USD", "EUR", "JPY", "CHF", "NGN", "GBP"]


def _best(pairs, rates, src):
    # Enumerate all simple paths (exponential, fine for tiny inputs) and keep
    # the maximum multiplier reaching each currency from src.
    adj = {}
    for (s, t), r in zip(pairs, rates):
        adj.setdefault(s, []).append((t, r))
        adj.setdefault(t, []).append((s, 1.0 / r))
    best = {src: 1.0}

    def dfs(node, val, visited):
        for nxt, mul in adj.get(node, []):
            if nxt in visited:
                continue
            nv = val * mul
            if nxt not in best or nv > best[nxt]:
                best[nxt] = nv
            visited.add(nxt)
            dfs(nxt, nv, visited)
            visited.remove(nxt)

    dfs(src, 1.0, {src})
    return best


def _is_forest(pairs):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for s, t in pairs:
        rs, rt = find(s), find(t)
        if rs == rt:
            return False
        parent[rs] = rt
    return True


