        init = json.loads(lines[0])
        p1 = json.loads(lines[1])
        r1 = json.loads(lines[2])
        p2 = json.loads(lines[3])
        r2 = json.loads(lines[4])
        if not (isinstance(init, str) and 1 <= len(init) <= 3
                and all("A" <= ch <= "Z" for ch in init)):
            return False
        if not (_check_day(p1, r1) and _check_day(p2, r2)):
            return False
        # Answer must fit the stated bound.
        return _ref_value(init, p1, r1, p2, r2) <= 5 * 10**10
    except Exception:
        return False


def _ref_value(init, p1, r1, p2, r2):
    d1 = _relax(p1, r1, init)
    best = 0.0
    for c, v in d1.items():
        d2 = _relax(p2, r2, c)
        if init in d2:
            best = max(best, v * d2[init])
    return best


def ref(inp):
    lines = inp.split("\n")
    init = json.loads(lines[0])
    p1 = json.loads(lines[1])
    r1 = json.loads(lines[2])
    p2 = json.loads(lines[3])
    r2 = json.loads(lines[4])
    return json.dumps(_ref_value(init, p1, r1, p2, r2))


def same(inp, expected, got):
    try:
        e = float(expected)
        g = float(got.strip())
        return abs(e - g) <= 1e-5 * max(1.0, abs(e))
    except Exception:
        return False
